/** Fee rates: copy their single Amount value; format on the consumer. */
template <> struct LogValue<CFeeRate> {
    // This is an in-process value snapshot, not a new wire serialization.
    // Avoid GetFeePerK(): it performs arithmetic which can overflow for rates
    // outside the monetary range even though ToString itself accepts them.
    static_assert(std::is_trivially_copyable_v<CFeeRate>);
    static_assert(std::has_unique_object_representations_v<CFeeRate>);
    static_assert(sizeof(CFeeRate) == sizeof(Amount));
    static constexpr size_t MAX_SIZE{sizeof(CFeeRate)};
    static size_t Pack(const CFeeRate &rate, std::span<std::byte> out) {
        std::memcpy(out.data(), &rate, sizeof(rate));
        return sizeof(rate);
    }
    static void Render(std::span<const std::byte> in, std::string &out) {
        CFeeRate rate;
        std::memcpy(&rate, in.data(), sizeof(rate));
        out += rate.ToString();
    }
};

/** Transactions, by reference:

BOOST_AUTO_TEST_CASE(fee_rate_value_is_snapshot_and_preserves_text) {
    Format(BCLog::LogFormat::JSON);
    const std::array<int64_t, 8> amounts{
        std::numeric_limits<int64_t>::min(), -100000001, -1, 0,
        1, 100000000, 100000001, std::numeric_limits<int64_t>::max()};
    for (const int64_t amount : amounts) {
        CFeeRate rate{amount * SATOSHI};
        const auto expected{rate.ToString()};
        std::array<std::byte, BCLog::LogValue<CFeeRate>::MAX_SIZE> packed;
        const auto size{BCLog::LogValue<CFeeRate>::Pack(rate, packed)};
        rate = CFeeRate{};
        std::string rendered;
        BCLog::LogValue<CFeeRate>::Render(std::span{packed}.first(size),
                                        rendered);
        BOOST_CHECK_EQUAL(rendered, expected);
    }
    CFeeRate rate{12345 * SATOSHI};
    const auto expected{rate.ToString()};
    LogInfoEvent(BCLog::ALL, "fee_rate_snapshot", "rate={fee_rate}")
        .Field(LogField::FeeRate, rate);
    rate = CFeeRate{};
    const auto record{Json()};
    BOOST_CHECK_EQUAL(record["fee_rate"].get_str(), expected);
    BOOST_CHECK_EQUAL(record["message"].get_str(), "rate=" + expected);
}

